/// Controls the fix kind emitted for a category of unused declaration.
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq, JsonSchema, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum NoUnusedVarsFixMode {
    /// Disables any auto-fix or suggestion for this category.
    Off,
    /// Emits a suggestion-style fix (default variant).
    #[default]
    Suggestion,
    /// Emits an automatic fix.
    Fix,
}

/// Holds per-category fix mode configuration.
#[derive(Debug, Default, Clone, JsonSchema, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct NoUnusedVarsFixOptions {
    /// Controls the fix mode for unused imports.
    pub imports: NoUnusedVarsFixMode,
    /// Controls the fix mode for unused variables (including catch bindings).
    pub variables: NoUnusedVarsFixMode,
}

impl TryFrom<&Value> for NoUnusedVarsFixMode {
    type Error = OxcDiagnostic;

    fn try_from(value: &Value) -> Result<Self, Self::Error> {
        match value {
            Value::String(s) => match s.as_str() {
                "off" => Ok(Self::Off),
                "suggestion" => Ok(Self::Suggestion),
                "fix" => Ok(Self::Fix),
                s => Err(invalid_option_mismatch_error(
                    "fix",
                    ["off", "suggestion", "fix"],
                    s,
                )),
            },
            v => Err(invalid_option_error("fix", format!("Expected a string, got {v}"))),
        }
    }
}

impl TryFrom<&Value> for NoUnusedVarsFixOptions {
    type Error = OxcDiagnostic;

    fn try_from(value: &Value) -> Result<Self, Self::Error> {
        match value {
            Value::Object(config) => {
                let imports = config
                    .get("imports")
                    .map(TryInto::try_into)
                    .transpose()?
                    .unwrap_or_default();
                let variables = config
                    .get("variables")
                    .map(TryInto::try_into)
                    .transpose()?
                    .unwrap_or_default();
                Ok(Self { imports, variables })
            }
            v => Err(invalid_option_error("fix", format!("Expected an object, got {v}"))),
        }
    }
